"""Binance A-level market data normalization helpers."""

from __future__ import annotations

from datetime import UTC, datetime
from decimal import Decimal
from typing import Iterable, Mapping, Sequence

from shared.models import MarketExtras, OHLCVBar

STABLE_OR_LEVERAGED_SUFFIXES = (
    "UP/USDT",
    "DOWN/USDT",
    "BULL/USDT",
    "BEAR/USDT",
)
STABLE_SYMBOLS = {"USDC/USDT", "FDUSD/USDT", "TUSD/USDT", "DAI/USDT", "USDP/USDT"}


class BinanceUniverseSelector:
    """Select liquid Binance USDT pairs for initial ingestion jobs."""

    def select_top_symbols(self, tickers: Mapping[str, Mapping], *, limit: int = 20) -> list[str]:
        ranked: list[tuple[str, Decimal]] = []
        for symbol, payload in tickers.items():
            if not symbol.endswith("/USDT"):
                continue
            if symbol in STABLE_SYMBOLS or symbol.endswith(STABLE_OR_LEVERAGED_SUFFIXES):
                continue
            quote_volume = payload.get("quoteVolume") or payload.get("quote_volume") or 0
            try:
                volume = Decimal(str(quote_volume))
            except Exception:
                volume = Decimal("0")
            ranked.append((symbol, volume))
        ranked.sort(key=lambda item: item[1], reverse=True)
        return [symbol for symbol, _ in ranked[:limit]]


def _from_millis(value: int | float | str) -> datetime:
    return datetime.fromtimestamp(int(value) / 1000, tz=UTC)


def normalize_ohlcv_rows(
    *, rows: Iterable[Sequence], symbol: str, timeframe: str, exchange: str = "binance"
) -> list[OHLCVBar]:
    """Normalize CCXT OHLCV rows into the platform OHLCV contract."""

    bars: list[OHLCVBar] = []
    for row in rows:
        if len(row) < 6:
            raise ValueError("OHLCV row must contain timestamp, open, high, low, close, volume")
        bars.append(
            OHLCVBar(
                symbol=symbol,
                exchange=exchange,
                timeframe=timeframe,
                time=_from_millis(row[0]),
                open=Decimal(str(row[1])),
                high=Decimal(str(row[2])),
                low=Decimal(str(row[3])),
                close=Decimal(str(row[4])),
                volume=Decimal(str(row[5])),
            )
        )
    return bars


def normalize_funding_rate_history(
    *, rows: Iterable[Mapping], symbol: str
) -> list[MarketExtras]:
    """Normalize Binance funding-rate records into MarketExtras."""

    extras: list[MarketExtras] = []
    for row in rows:
        timestamp = row.get("timestamp") or row.get("fundingTime") or row.get("time")
        if timestamp is None:
            raise ValueError("funding row missing timestamp")
        rate = row.get("fundingRate") or row.get("funding_rate")
        extras.append(
            MarketExtras(
                symbol=symbol,
                time=_from_millis(timestamp),
                funding_rate=Decimal(str(rate)) if rate is not None else None,
            )
        )
    return extras

"""Shared validation metrics for strategy backtests."""

from __future__ import annotations

import math
from decimal import Decimal
from statistics import mean, pstdev


def profit_factor(pnls: list[Decimal]) -> float:
    wins = [pnl for pnl in pnls if pnl > 0]
    losses = [pnl for pnl in pnls if pnl < 0]
    if not losses:
        return 9.99 if wins else 0.0
    return float(sum(wins, Decimal("0")) / abs(sum(losses, Decimal("0"))))


def expectancy(pnls: list[Decimal]) -> float:
    return float(sum(pnls, Decimal("0")) / len(pnls)) if pnls else 0.0


def win_rate(pnls: list[Decimal]) -> float:
    return len([pnl for pnl in pnls if pnl > 0]) / len(pnls) if pnls else 0.0


def annualized_sharpe(returns: list[float], *, periods_per_year: float) -> float:
    if len(returns) < 2:
        return 0.0
    avg = mean(returns)
    volatility = pstdev(returns)
    if volatility == 0:
        return 0.0
    return (avg / volatility) * math.sqrt(periods_per_year)


def max_drawdown_from_pnls(pnls: list[Decimal], *, initial_equity: Decimal) -> float:
    if initial_equity <= 0:
        raise ValueError("initial_equity must be positive")
    equity = initial_equity
    peak = initial_equity
    max_drawdown = Decimal("0")
    for pnl in pnls:
        equity += pnl
        if equity > peak:
            peak = equity
        drawdown = (peak - equity) / peak if peak > 0 else Decimal("0")
        if drawdown > max_drawdown:
            max_drawdown = drawdown
    return float(max_drawdown)


def deflated_sharpe(
    sharpe: float,
    returns: list[float],
    *,
    trials_count: int | None,
) -> float:
    """Conservatively deflate Sharpe for repeated trials.

    This implements a lightweight Bailey/Lopez de Prado style correction:
    subtract the expected maximum Sharpe inflation from multiple trials. The
    correction is intentionally dependency-free and monotonic in trials_count.
    """

    if len(returns) < 2:
        return 0.0
    trials = max(int(trials_count or 1), 1)
    if trials == 1:
        return sharpe
    sample_size = len(returns)
    penalty = math.sqrt(2.0 * math.log(trials)) / math.sqrt(sample_size)
    return sharpe - penalty


def sharpe_confidence(sharpe: float, *, sample_size: int) -> float:
    if sample_size <= 1:
        return 0.0
    z_score = sharpe * math.sqrt(sample_size - 1)
    return 0.5 * (1.0 + math.erf(z_score / math.sqrt(2.0)))

