### React Component with createChart, addSeries, setData, useEffect cleanup with remove()

Source: https://github.com/tradingview/lightweight-charts/blob/master/website/src/components/landing-page/HeroChart/index.tsx

Complete React example demonstrating v5 createChart with AreaSeries, setData, React useEffect hook with proper cleanup using chart.remove(), and applyOptions for dark/light theme switching based on layout options.

```typescript
function Chart(): React.JSX.Element {
	const ref = React.useRef<HTMLDivElement>(null);
	const layout = useThemeAwareLayoutOptions();
	const [chart, setChart] = React.useState<IChartApi | null>(null);
	const [areaSeries, setAreaSeries] = React.useState<ISeriesApi<'Area'> | null>(null);

	React.useEffect(
		() => {
			const container = ref.current;

			if (!container) {
				return;
			}

			const c = createChart(container, {
				layout,
				rightPriceScale: {
					borderVisible: false,
					autoScale: false,
				},
			});

			const aS = c.addSeries(AreaSeries, {
				lineColor: '#2962ff',
				topColor: '#2962ff',
				bottomColor: 'rgba(41, 98, 255, 0.28)',
				lineWidth: 2,
			});

			aS.setData(chartData);

			setChart(c);
			setAreaSeries(aS);

			return () => {
				c.remove();
				setChart(null);
			};
		},
		[]
	);

	React.useEffect(
		() => {
			if (!chart || !ref.current) {
				return;
			}

			chart.applyOptions({
				layout: {
					fontSize: 12,
				},
			});
		},
		[chart]
	);

	React.useEffect(
		() => {
			if (!chart) {
				return;
			}

			chart.applyOptions({ layout });
		},
		[layout, chart]
	);

	return <div className={styles.ChartContainer} ref={ref}></div>;
}
```

